// SPDX-License-Identifier: MIT
/// @title Dummy version of the governance treasury contract.
/// @notice This contract is only a placeholder to enable compilation and interaction for other contracts, and will be replaced at UDAO version 2.0 with a functional contract.
/// @dev This contract is intended to distribute the accumulated pool balances for jurors, validators, and governance to respective individuals in future functionalities.
pragma solidity ^0.8.4;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";

contract GovernanceTreasury {
    // UDAO (ERC20) Token contract address
    IERC20 udao;

    /// @notice Balance of jurors, its a pool for jurors transferred from platform treasury.
    uint jurorBalance;
    /// @notice Balance of validators, its a pool for validators transferred from platform treasury.
    uint validatorBalance;
    /// @notice Balance of governance, its a pool for governance transferred from platform treasury.
    uint governanceBalance;

    /// @notice Address of the deployer of this dummy contract
    address ownerOfDummy;

    /// @notice Constructor function of governance treasury contract.
    /// @param udaoAddress Address of the UDAO token contract.
    constructor(address udaoAddress) {
        udao = IERC20(udaoAddress);
        ownerOfDummy = msg.sender;
    }

    /// @notice Updates the jurors balance in this treasury.
    /// @param _balance The balance to update.
    function jurorBalanceUpdate(uint _balance) external {
        jurorBalance += _balance;
    }

    /// @notice Updates the validators balance in this treasury.
    /// @param _balance The balance to update.
    function validatorBalanceUpdate(uint _balance) external {
        validatorBalance += _balance;
    }

    /// @notice Updates the governance balance in this treasury.
    /// @param _balance The balance to update.
    function governanceBalanceUpdate(uint _balance) external {
        governanceBalance += _balance;
    }

    /// @notice Withdraws the balance of the treasury.
    /// @dev this dummy contract should not accumulate any balance, if any at all it an unwanted behaviour and deployer can save the funds.
    function emergencyWithdraw() external {
        require(
            msg.sender == ownerOfDummy,
            "you are not owner of dummy contract"
        );
        udao.transfer(msg.sender, udao.balanceOf(address(this)));
        validatorBalance = 0;
        jurorBalance = 0;
        governanceBalance = 0;
    }
}

contracts/treasury/PlatformTreasury.sol.content:
// SPDX-License-Identifier: MIT
/// @title Platform Treasury contract for the UDAO Platform's primary financial operations.
/// @author anywaiTR: Bugrahan Duran, Batuhan Darcin
/// @notice This contract manages revenue distribution and withdrawals for the UDAO Platform, inheriting critical functionalities from the ContentManager and BasePlatform contracts.
/// @dev The contract facilitates platform revenue distribution, role dependent revenue share management, and instructor withdrawals based on a refund window mechanism.

pragma solidity ^0.8.4;
import "./ContentManager.sol";

contract PlatformTreasury is ContentManager {
    ///@notice this event gets triggered when founcation withdraw tokens
    /// @param amount The amount of tokens withdrawn
    event FoundationWithdrawn(uint amount);
    ///@notice this event gets triggered when a instructor withdraw tokens
    /// @param instructor The address of the instructor
    /// @param amount The amount of tokens withdrawn
    /// @param debt The amount of tokens that are not withdrawn due to the debt
    event InstructorWithdrawn(
        address indexed instructor,
        uint amount,
        uint debt
    );
    /// @notice this event gets triggered when the refund window is updated
    /// @param newWindow The new refund window period
    event RefundWindowUpdated(uint newWindow);

    /// @notice constructor of the PlatformTreasury contract
    /// @param _rmAddress The address of the deployed role manager
    /// @param _udaoAddress The address of the deployed UDAO token
    /// @param _udaocAddress The address of the deployed UDAOC token
    /// @param _governanceTreasuryAddress The address of the deployed governance treasury
    /// @param _voucherVerifierAddress The address of the deployed voucher verifier
    constructor(
        address _rmAddress,
        address _udaoAddress,
        address _udaocAddress,
        address _governanceTreasuryAddress,
        address _voucherVerifierAddress
    )
        BasePlatform(
            _rmAddress,
            _udaoAddress,
            _udaocAddress,
            _governanceTreasuryAddress,
            _voucherVerifierAddress
        )
    {}

    /// @notice Allows anyone to update the platform cut balances and transfer the platform cut to governance
    function updateAndTransferPlatformBalances() external {
        /// @dev this is the timestamp of the transaction in days
        uint256 transactionTime = (block.timestamp / 86400);
        /// @dev transactionLBIndex determines a "transaction time dependent position" in the Locked balanaces array.
        uint256 transactionLBIndex = transactionTime % refundWindow;
        /// @dev update platform cut (coaching&content) pools and platform locked pools
        _updatePlatformCutBalances(
            0, //contentCut=0 due to there is no content revenue on this transaction
            0, //coachingCut=0 due to there is no coaching revenue on this transaction
            transactionTime,
            transactionLBIndex
        );
        /// @dev update instructor balance and instructor locked balances,
        _updateInstructorBalances(
            0, //instShare=0 due to there is no new revenue on this transaction
            msg.sender,
            transactionTime,
            transactionLBIndex
        );
        /// @dev if there is any revenue in platform cut pools, distribute role shares to roles and transfer governance role shares to governance treasury
        _transferPlatformCutstoGovernance();
    }

    /// @notice withdraws foundation balance to foundation wallet
    function withdrawFoundation() external whenNotPaused {
        require(
            hasRole(FOUNDATION_ROLE, msg.sender),
            "Only foundation can withdraw"
        );
        /// @dev this is the timestamp of the transaction in days
        uint256 transactionTime = (block.timestamp / 86400);
        /// @dev transactionLBIndex determines a "transaction time dependent position" in the Locked balanaces array.
        uint256 transactionLBIndex = transactionTime % refundWindow;
        /// @dev update platform cut (coaching&content) pools and platform locked pools
        _updatePlatformCutBalances(
            0, //contentCut=0 due to there is no content revenue on this transaction
            0, //coachingCut=0 due to there is no coaching revenue on this transaction
            transactionTime,
            transactionLBIndex
        );
        /// @dev if there is any revenue in platform cut pools, distribute role shares to roles and transfer governance role shares to governance treasury
        _transferPlatformCutstoGovernance();
        /// @dev calculate the withdrawable balance of foundation
        uint withdrawableBalance = foundationBalance;
        /// @dev zeroing before the actual withdraw
        foundationBalance = 0; /// @dev zeroing before the actual withdraw
        /// @dev transfer the withdrawable balance to the foundation wallet
        udao.transfer(foundationWallet, withdrawableBalance);

        emit FoundationWithdrawn(withdrawableBalance);
    }

    /// @notice Allows instructers to withdraw individually.
    function withdrawInstructor() external whenNotPaused {
        require(
            block.timestamp > precautionWithdrawalTimestamp,
            "Precaution withdrawal period is not over"
        );

        uint positiveBalance;
        uint refundedBalance;
        (positiveBalance, refundedBalance) = getWithdrawableBalanceInstructor(
            msg.sender
        );
        require(positiveBalance > 0, "No balance to withdraw");
        require(
            positiveBalance - refundedBalance > 0,
            "Debt is larger than or equal to balance"
        );
        /// @dev this is the timestamp of the transaction in days
        uint256 transactionTime = (block.timestamp / 86400);
        /// @dev transactionLBIndex determines a "transaction time dependent position" in the Locked balanaces array.
        uint256 transactionLBIndex = transactionTime % refundWindow;
        /// @dev update platform cut (coaching&content) pools and platform locked pools
        _updatePlatformCutBalances(
            0, //contentCut=0 due to there is no content revenue on this transaction
            0, //coachingCut=0 due to there is no coaching revenue on this transaction
            transactionTime,
            transactionLBIndex
        );
        /// @dev if there is any revenue in platform cut pools, distribute role shares to roles and transfer governance role shares to governance treasury
        _transferPlatformCutstoGovernance();
        /// @dev update instructor balance and instructor locked balances,
        _updateInstructorBalances(
            0, //instShare=0 due to there is no new revenue on this transaction
            msg.sender,
            transactionTime,
            transactionLBIndex
        );

        /// @dev calculate the debt(refunded and blocked balance) amount and withdrawable balance of the instructor
        uint debtAmount = instRefundedBalance[msg.sender];
        uint withdrawableBalance = instBalance[msg.sender] - debtAmount;
        /// @dev zeroing before the actual withdraw
        instBalance[msg.sender] = 0;
        instRefundedBalance[msg.sender] = 0;
        /// @dev transfer the withdrawable balance to the instructor
        udao.transfer(msg.sender, withdrawableBalance);

        emit InstructorWithdrawn(msg.sender, withdrawableBalance, debtAmount);
    }

    /// @notice returns the withdrawable balance of the instructor
    /// @param _inst The address of the instructor
    /// @return withdrawableBalance The withdrawable balance of the given instructor
    function getWithdrawableBalanceInstructor(
        address _inst
    ) public view returns (uint, uint) {
        uint instPositiveBalanceOnLock;
        uint instCurrentPositiveBalance;
        instCurrentPositiveBalance += instBalance[_inst];

        if (prevInstRefundWindow[_inst] == refundWindow) {
            /// @dev this is the timestamp of the transaction in days
            uint256 transactionTime = (block.timestamp / 86400);
            /// @dev transactionLBIndex determines a "transaction time dependent position" in the Locked balanaces array.
            uint256 transactionLBIndex = transactionTime % refundWindow;

            uint256 dayPassedInst = transactionTime - instLockTime[_inst];
            if (dayPassedInst >= refundWindow) {
                uint256 dayPassedInstMod;
                /// @dev if the instructor is locked for more than 2 refund window, the instructor will be able to withdraw all the locked balance
                if (dayPassedInst >= (refundWindow * 2)) {
                    dayPassedInstMod = refundWindow - 1;
                } else {
                    dayPassedInstMod = dayPassedInst % refundWindow;
                }
                /// @dev calculate the positive balance of the instructor
                for (uint256 i = 0; i <= dayPassedInstMod; i++) {
                    //Index of the day to be payout to instructor.
                    uint256 indexOfPayout = ((transactionLBIndex +
                        refundWindow) - i) % refundWindow;
                    instPositiveBalanceOnLock += instLockedBalance[_inst][
                        indexOfPayout
                    ];
                }
            }
        }
        /// @dev return the calculated positive balance and refunded balance of the instructor
        return (
            instCurrentPositiveBalance + instPositiveBalanceOnLock,
            instRefundedBalance[_inst]
        );
    }

    /// @notice Allows backend to change platform refun window period
    /// @param _newWindow The new refund window period
    function changeRefundWindow(uint256 _newWindow) external {
        require(
            hasRole(BACKEND_ROLE, msg.sender),
            "Only backend can set refund window"
        );
        require(
            _newWindow >= 2,
            "Refund window period should be at least 2 days"
        );
        require(
            _newWindow <= 60,
            "Refund window period should be at most 60 days"
        );
        require(
            _newWindow != refundWindow,
            "New window period is the same as the current one"
        );
        /// @dev this is the timestamp of the transaction in days
        uint256 transactionTime = (block.timestamp / 86400);
        /// @dev transactionLBIndex determines a "transaction time dependent position" in the Locked balanaces array.
        uint256 transactionLBIndex = transactionTime % refundWindow;
        /// @dev update platform cut (coaching&content) pools and platform locked pools
        _updatePlatformCutBalances(
            0, //contentCut=0 due to there is no content revenue on this transaction
            0, //coachingCut=0 due to there is no coaching revenue on this transaction
            transactionTime,
            transactionLBIndex
        );
        /// @dev if there is any revenue in platform cut pools, distribute role shares to roles and transfer governance role shares to governance treasury
        _transferPlatformCutstoGovernance();
        /// @dev locked balances will be emptied and re-added to the platform cut pools
        uint256 emptiedContentCutPool;
        uint256 emptiedCoachingCutPool;
        /// @dev save the possession of locked balances and empty the locked balances
        for (uint256 i = 0; i < refundWindow; i++) {
            emptiedContentCutPool += contentCutLockedPool[i];
            contentCutLockedPool[i] = 0;
            emptiedCoachingCutPool += coachingCutLockedPool[i];
            coachingCutLockedPool[i] = 0;
        }

        if (refundWindow > _newWindow) {
            uint temp = block.timestamp + (refundWindow * 86400);
            if (temp > precautionWithdrawalTimestamp) {
                precautionWithdrawalTimestamp = temp;
            }
        }

        refundWindow = _newWindow;
        emit RefundWindowUpdated(_newWindow);

        /// @dev transactionLBIndex determines a "transaction time dependent position" in the Locked balanaces array.
        transactionLBIndex = transactionTime % refundWindow;
        /// @dev update platform cut (coaching&content) pools and platform locked pools
        _updatePlatformCutBalances(
            emptiedContentCutPool,
            emptiedCoachingCutPool,
            transactionTime,
            transactionLBIndex
        );
    }
}

contracts/treasury/VoucherVerifier.sol.content:
// SPDX-License-Identifier: MIT
/// @title Main contract for voucher verification of platform treasury
pragma solidity ^0.8.4;

import "../RoleLegacy.sol";
import "../interfaces/IRoleManager.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/utils/cryptography/draft-EIP712.sol";

contract VoucherVerifier is EIP712, RoleLegacy {
    string private constant SIGNING_DOMAIN = "TreasuryVouchers";
    string private constant SIGNATURE_VERSION = "1";

    constructor(
        address roleManagerAddress
    ) EIP712(SIGNING_DOMAIN, SIGNATURE_VERSION) {
        roleManager = IRoleManager(roleManagerAddress);
    }

    /// @notice This event is triggered if the contract manager updates the addresses.
    event AddressesUpdated(address roleManagerAddress);

    /// @notice struct to hold content discount voucher information
    /// @param tokenId id of the content
    /// @param fullContentPurchase is full content purchased
    /// @param purchasedParts parts of the content purchased
    /// @param priceToPay price to pay
    /// @param validUntil date until the voucher is valid
    /// @param redeemer address of the redeemer
    /// @param giftReceiver address of the gift receiver if purchase is a gift or fiat purchase
    /// @param userId user id of the redeemer
    /// @param signature the EIP-712 signature of all other fields in the ContentDiscountVoucher struct.
    struct ContentDiscountVoucher {
        uint256 tokenId;
        bool fullContentPurchase;
        uint256[] purchasedParts;
        uint256 priceToPay;
        uint256 validUntil;
        address redeemer;
        address giftReceiver;
        string userId;
        bytes signature;
    }
    /// @notice Represents a refund voucher for a coaching
    /// @param saleID id of the sale to be refunded
    /// @param instructor address of the instructor
    /// @param finalParts parts that will remain in the learner's wallet after refund
    /// @param finalContents contents that will remain in the learner's wallet after refund
    /// @param validUntil date until the voucher is valid
    /// @param signature the EIP-712 signature of all other fields in the RefundVoucher struct.
    struct RefundVoucher {
        uint256 saleID;
        address instructor;
        uint256[] finalParts;
        uint256[] finalContents;
        uint256 validUntil;
        bytes signature;
    }

    /// @notice struct to hold coaching voucher information
    /// @param coach address of the coach
    /// @param priceToPay price to pay
    /// @param coachingDate date of the coaching
    /// @param learner address of the learner
    /// @param userId user id of the learner
    /// @param signature the EIP-712 signature of all other fields in the CoachingVoucher struct.
    struct CoachingVoucher {
        address coach;
        uint256 priceToPay;
        uint256 coachingDate;
        address learner;
        string userId;
        bytes signature;
    }

    /// @notice Get the updated addresses from contract manager
    /// @param roleManagerAddress The address of the role manager contract
    function updateAddresses(address roleManagerAddress) external {
        if (msg.sender != foundationWallet) {
            require(
                (hasRole(BACKEND_ROLE, msg.sender) ||
                    hasRole(CONTRACT_MANAGER, msg.sender)),
                "Only backend and contract manager can update addresses"
            );
        }
        roleManager = IRoleManager(roleManagerAddress);

        emit AddressesUpdated(roleManagerAddress);
    }

    /// @notice Returns a hash of the given ContentDiscountVoucher, prepared using EIP712 typed data hashing rules.
    /// @param voucher A ContentDiscountVoucher to hash.
    function _hashDiscountVoucher(
        ContentDiscountVoucher calldata voucher
    ) internal view returns (bytes32) {
        return
            _hashTypedDataV4(
                keccak256(
                    abi.encode(
                        keccak256(
                            "ContentDiscountVoucher(uint256 tokenId,bool fullContentPurchase,uint256[] purchasedParts,uint256 priceToPay,uint256 validUntil,address redeemer,address giftReceiver,string userId)"
                        ),
                        voucher.tokenId,
                        voucher.fullContentPurchase,
                        keccak256(abi.encodePacked(voucher.purchasedParts)),
                        voucher.priceToPay,
                        voucher.validUntil,
                        voucher.redeemer,
                        voucher.giftReceiver,
                        keccak256(bytes(voucher.userId))
                    )
                )
            );
    }

    /// @notice Returns a hash of the given RefundVoucher, prepared using EIP712 typed data hashing rules.
    /// @param voucher A RefundVoucher to hash.
    function _hashRefundVoucher(
        RefundVoucher calldata voucher
    ) internal view returns (bytes32) {
        return
            _hashTypedDataV4(
                keccak256(
                    abi.encode(
                        keccak256(
                            "RefundVoucher(uint256 saleID,address instructor,uint256[] finalParts,uint256[] finalContents,uint256 validUntil)"
                        ),
                        voucher.saleID,
                        voucher.instructor,
                        keccak256(abi.encodePacked(voucher.finalParts)),
                        keccak256(abi.encodePacked(voucher.finalContents)),
                        voucher.validUntil
                    )
                )
            );
    }

    /// @notice Returns a hash of the given CoachingVoucher, prepared using EIP712 typed data hashing rules.
    /// @param voucher A CoachingVoucher to hash.
    function _hashCoachingVoucher(
        CoachingVoucher calldata voucher
    ) internal view returns (bytes32) {
        return
            _hashTypedDataV4(
                keccak256(
                    abi.encode(
                        keccak256(
                            "CoachingVoucher(address coach,uint256 priceToPay,uint256 coachingDate,address learner,string userId)"
                        ),
                        voucher.coach,
                        voucher.priceToPay,
                        voucher.coachingDate,
                        voucher.learner,
                        keccak256(bytes(voucher.userId))
                    )
                )
            );
    }

    /// @notice Verifies the signature for a given ContentDiscountVoucher, returning the address of the signer.
    /// @dev Will revert if the signature is invalid.
    /// @param voucher A ContentDiscountVoucher describing a content purchase.
    function verifyDiscountVoucher(
        ContentDiscountVoucher calldata voucher
    ) external view {
        bytes32 digest = _hashDiscountVoucher(voucher);

        // make sure signature is valid and get the address of the signer
        address signer = ECDSA.recover(digest, voucher.signature);
        require(
            roleManager.hasRole(VOUCHER_VERIFIER, signer),
            "Signature invalid or unauthorized"
        );
        require(voucher.validUntil >= block.timestamp, "Voucher has expired.");
    }

    /// @notice Verifies the signature for a given RefundVoucher, returning the address of the signer.
    /// @dev Will revert if the signature is invalid.
    /// @param voucher A RefundVoucher describing a refund.
    function verifyRefundVoucher(RefundVoucher calldata voucher) external view {
        bytes32 digest = _hashRefundVoucher(voucher);
        address signer = ECDSA.recover(digest, voucher.signature);
        require(
            roleManager.hasRole(VOUCHER_VERIFIER, signer),
            "Signature invalid or unauthorized"
        );
    }

    /// @notice Verifies the signature for a given CoachingVoucher, returning the address of the signer.
    /// @dev Will revert if the signature is invalid.
    /// @param voucher A CoachingVoucher describing a coaching purchase.
    function verifyCoachingVoucher(
        CoachingVoucher calldata voucher
    ) external view {
        bytes32 digest = _hashCoachingVoucher(voucher);
        address signer = ECDSA.recover(digest, voucher.signature);
        require(
            signer == voucher.coach ||
                roleManager.hasRole(VOUCHER_VERIFIER, signer),
            "Signature invalid or unauthorized"
        );
    }

    /// @notice Returns the chain id of the current blockchain.
    /// @dev This is used to workaround an issue with ganache returning different values from the on-chain chainid() function and
    ///  the eth_chainId RPC method. See https://github.com/protocol/nft-website/issues/121 for context.
    function getChainID() external view returns (uint256) {
        uint256 id;
        assembly {
            id := chainid()
        }
        return id;
    }
}

